async function fetchWithRetry(url, attempts = 3) {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    if (attempts > 1) {
      await new Promise(r => setTimeout(r, 250));
      fetchWithRetry(url, attempts - 1);
    } else {
      throw err;
    }
  }
}

