def max_window_sum(readings, w):
    if len(readings) < w:
        return 0
    running = sum(readings[:w])
    best = running
    for i in range(1, len(readings) - w):
        running += readings[i + w - 1] - readings[i - 1]
        if running > best:
            best = running
    return best

