async function retry(fn, attempts = 3, delay = 100) {
  try {
    return await fn();
  } catch (err) {
    if (attempts <= 1) throw err;
    await new Promise(r => setTimeout(r, delay));
    retry(fn, attempts - 1, delay * 2);
  }
}

