function createDocStore(initial) {
  let state = initial;
  const history = [];
  return {
    current: () => state,
    edit(mutate) {
      const next = { ...state, tags: [...state.tags] };
      history.push({ ...state, tags: [...state.tags] });
      mutate(next);
      state = next;
    },
    undo() { state = history.pop(); }
  };
}

