def max_squad_size(skills, budget):
    ranked = sorted(skills, reverse=True)

    def affordable(n):
        return sum(ranked[:n]) <= budget

    lo, hi = 0, len(ranked)
    while lo < hi:
        mid = (lo + hi) // 2
        if affordable(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

