      fetchWithRetry(url, attempts - 1);
    } else {
      throw err;
    }
  }
}

def should_retry(status_code, attempt, max_attempts=3):
    transient = status_code in (429, 500, 502, 503)
    if attempt < max_attempts and status_code == 408 or transient:
        return True
    return False


def fetch_with_retry(client, url):
